import{_ as s,c as a,a as p,o as e}from"./app-BRIJxD8h.js";const t={};function l(i,n){return e(),a("div",null,[...n[0]||(n[0]=[p(`<h1 id="указатели-в-структурах" tabindex="-1"><a class="header-anchor" href="#указатели-в-структурах"><span>Указатели в структурах</span></a></h1><p>Продолжаем изучение Go! Указатели в структурах — это мощный инструмент, который позволяет работать с данными эффективно. В Go структуры (structs) — это составные типы данных, как классы в других языках, но без наследования. Указатели могут использоваться в структурах двумя основными способами:</p><ol><li><strong>Как поля внутри структуры</strong>: Поле типа <code>*T</code> (указатель на какой-то тип). Это полезно для &quot;опциональных&quot; полей (может быть nil), ссылок на другие данные или экономии памяти (вместо встраивания больших объектов).</li><li><strong>В методах структур (pointer receivers)</strong>: Метод объявляется с приёмником <code>*Struct</code>, чтобы изменять оригинальную структуру. Без этого метод работает с копией.</li></ol><p><strong>Зачем указатели в структурах?</strong></p><ul><li><strong>Изменяемость</strong>: Структуры передаются по значению (копируются). Указатели позволяют изменять оригинал без копирования.</li><li><strong>Экономия</strong>: Для больших структур копирование дорого. Указатель — всего 8 байт (на 64-битной системе).</li><li><strong>Опциональность</strong>: Поле-указатель может быть nil, что значит &quot;нет значения&quot; (в отличие от zero-value, как пустая строка).</li><li><strong>Ссылки</strong>: Структуры могут ссылаться друг на друга (например, в деревьях или графах).</li><li><strong>Методы</strong>: Pointer receivers позволяют методам мутировать структуру, как в OOP.</li></ul><p><strong>Важно</strong>: В Go старайся использовать указатели только когда нужно (для изменений или nil). Иначе используй value types для простоты и безопасности. Всегда проверяй на nil, чтобы избежать panic.</p><p>Давай разберём на примерах. Код можно скопировать и запустить (<code>go run main.go</code>).</p><h4 id="пример-1-указатель-как-поле-в-структуре-опциональное-поле" tabindex="-1"><a class="header-anchor" href="#пример-1-указатель-как-поле-в-структуре-опциональное-поле"><span>Пример 1: Указатель как поле в структуре (опциональное поле)</span></a></h4><p>Здесь структура имеет поле-указатель на int. Это позволяет полю быть nil.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token string">&quot;fmt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Employee <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Name <span class="token builtin">string</span></span>
<span class="line">    Age  <span class="token operator">*</span><span class="token builtin">int</span>  <span class="token comment">// Указатель на int (может быть nil)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Создаём структуру без возраста</span></span>
<span class="line">    e1 <span class="token operator">:=</span> Employee<span class="token punctuation">{</span>Name<span class="token punctuation">:</span> <span class="token string">&quot;Alice&quot;</span><span class="token punctuation">}</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;e1:&quot;</span><span class="token punctuation">,</span> e1<span class="token punctuation">.</span>Name<span class="token punctuation">,</span> <span class="token string">&quot;Age:&quot;</span><span class="token punctuation">,</span> e1<span class="token punctuation">.</span>Age<span class="token punctuation">)</span>  <span class="token comment">// Alice Age: &lt;nil&gt;</span></span>
<span class="line">    </span>
<span class="line">    <span class="token keyword">if</span> e1<span class="token punctuation">.</span>Age <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Возраст Alice не указан&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Создаём с возрастом</span></span>
<span class="line">    age <span class="token operator">:=</span> <span class="token number">30</span></span>
<span class="line">    e2 <span class="token operator">:=</span> Employee<span class="token punctuation">{</span>Name<span class="token punctuation">:</span> <span class="token string">&quot;Bob&quot;</span><span class="token punctuation">,</span> Age<span class="token punctuation">:</span> <span class="token operator">&amp;</span>age<span class="token punctuation">}</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;e2:&quot;</span><span class="token punctuation">,</span> e2<span class="token punctuation">.</span>Name<span class="token punctuation">,</span> <span class="token string">&quot;Age:&quot;</span><span class="token punctuation">,</span> <span class="token operator">*</span>e2<span class="token punctuation">.</span>Age<span class="token punctuation">)</span>  <span class="token comment">// Bob Age: 30</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Меняем через указатель</span></span>
<span class="line">    <span class="token operator">*</span>e2<span class="token punctuation">.</span>Age <span class="token operator">=</span> <span class="token number">31</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Новый возраст Bob:&quot;</span><span class="token punctuation">,</span> <span class="token operator">*</span>e2<span class="token punctuation">.</span>Age<span class="token punctuation">)</span>  <span class="token comment">// 31</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Оригинальный age:&quot;</span><span class="token punctuation">,</span> age<span class="token punctuation">)</span>       <span class="token comment">// 31 (изменился, т.к. указатель)</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Делаем nil</span></span>
<span class="line">    e2<span class="token punctuation">.</span>Age <span class="token operator">=</span> <span class="token boolean">nil</span></span>
<span class="line">    <span class="token keyword">if</span> e2<span class="token punctuation">.</span>Age <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Возраст Bob удалён&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>Что происходит?</strong> Поле <code>Age</code> может быть nil (нет возраста) или указывать на int. Это полезно в моделях данных (например, в JSON: nil — null).</li><li><strong>Зачем?</strong> Для полей, которые не всегда заполнены (опциональные атрибуты в БД или API).</li></ul><h4 id="пример-2-указатели-в-методах-структур-pointer-receivers" tabindex="-1"><a class="header-anchor" href="#пример-2-указатели-в-методах-структур-pointer-receivers"><span>Пример 2: Указатели в методах структур (pointer receivers)</span></a></h4><p>Методы в Go — это функции с &quot;приёмником&quot; (receiver). Если receiver — <code>*Struct</code>, метод может изменять структуру.</p><p>Без указателя (value receiver — копия):</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token string">&quot;fmt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Counter <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Value <span class="token builtin">int</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Value receiver: работает с копией</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>c Counter<span class="token punctuation">)</span> <span class="token function">Increment</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    c<span class="token punctuation">.</span>Value<span class="token operator">++</span>  <span class="token comment">// Изменяет копию</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    cnt <span class="token operator">:=</span> Counter<span class="token punctuation">{</span>Value<span class="token punctuation">:</span> <span class="token number">5</span><span class="token punctuation">}</span></span>
<span class="line">    cnt<span class="token punctuation">.</span><span class="token function">Increment</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>cnt<span class="token punctuation">.</span>Value<span class="token punctuation">)</span>  <span class="token comment">// 5 (не изменилось)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>С указателем (pointer receiver):</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token string">&quot;fmt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Counter <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Value <span class="token builtin">int</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Pointer receiver: изменяет оригинал</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>c <span class="token operator">*</span>Counter<span class="token punctuation">)</span> <span class="token function">Increment</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    c<span class="token punctuation">.</span>Value<span class="token operator">++</span>  <span class="token comment">// Без * (Go упрощает)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    cnt <span class="token operator">:=</span> Counter<span class="token punctuation">{</span>Value<span class="token punctuation">:</span> <span class="token number">5</span><span class="token punctuation">}</span></span>
<span class="line">    cnt<span class="token punctuation">.</span><span class="token function">Increment</span><span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token comment">// Go автоматически берёт &amp;cnt</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>cnt<span class="token punctuation">.</span>Value<span class="token punctuation">)</span>  <span class="token comment">// 6</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Явно с указателем</span></span>
<span class="line">    ptr <span class="token operator">:=</span> <span class="token operator">&amp;</span>cnt</span>
<span class="line">    ptr<span class="token punctuation">.</span><span class="token function">Increment</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>cnt<span class="token punctuation">.</span>Value<span class="token punctuation">)</span>  <span class="token comment">// 7</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>Что происходит?</strong> Pointer receiver позволяет методу мутировать структуру. Go позволяет вызывать метод на value (cnt.Increment()), автоматически беря адрес (&amp;).</li><li><strong>Зачем?</strong> Для методов вроде &quot;Update&quot;, &quot;Reset&quot; в объектах (например, в играх или UI). Рекомендация: Используй pointer receivers, если метод меняет структуру или структура большая.</li></ul><h4 id="пример-3-передача-структуры-по-указателю-в-функцию" tabindex="-1"><a class="header-anchor" href="#пример-3-передача-структуры-по-указателю-в-функцию"><span>Пример 3: Передача структуры по указателю в функцию</span></a></h4><p>Структуры копируются при передаче. Указатель позволяет изменить оригинал.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token string">&quot;fmt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Point <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    X<span class="token punctuation">,</span> Y <span class="token builtin">int</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">moveBad</span><span class="token punctuation">(</span>p Point<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    p<span class="token punctuation">.</span>X <span class="token operator">+=</span> <span class="token number">10</span>  <span class="token comment">// Меняем копию</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">moveGood</span><span class="token punctuation">(</span>p <span class="token operator">*</span>Point<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    p<span class="token punctuation">.</span>X <span class="token operator">+=</span> <span class="token number">10</span>  <span class="token comment">// Меняем оригинал</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    pt <span class="token operator">:=</span> Point<span class="token punctuation">{</span>X<span class="token punctuation">:</span> <span class="token number">5</span><span class="token punctuation">,</span> Y<span class="token punctuation">:</span> <span class="token number">0</span><span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token function">moveBad</span><span class="token punctuation">(</span>pt<span class="token punctuation">)</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;После moveBad:&quot;</span><span class="token punctuation">,</span> pt<span class="token punctuation">.</span>X<span class="token punctuation">)</span>  <span class="token comment">// 5 (не изменилось)</span></span>
<span class="line">    </span>
<span class="line">    <span class="token function">moveGood</span><span class="token punctuation">(</span><span class="token operator">&amp;</span>pt<span class="token punctuation">)</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;После moveGood:&quot;</span><span class="token punctuation">,</span> pt<span class="token punctuation">.</span>X<span class="token punctuation">)</span>  <span class="token comment">// 15</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>Зачем?</strong> Для функций, модифицирующих структуры (например, обновление координат в графике). Экономит память для больших структур.</li></ul><h4 id="пример-4-структуры-с-указателями-на-другие-структуры-ссылки" tabindex="-1"><a class="header-anchor" href="#пример-4-структуры-с-указателями-на-другие-структуры-ссылки"><span>Пример 4: Структуры с указателями на другие структуры (ссылки)</span></a></h4><p>Указатели позволяют структурам ссылаться друг на друга, как в linked lists или trees.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token string">&quot;fmt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Node <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Value <span class="token builtin">int</span></span>
<span class="line">    Next  <span class="token operator">*</span>Node  <span class="token comment">// Указатель на следующую Node</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>n <span class="token operator">*</span>Node<span class="token punctuation">)</span> <span class="token function">PrintChain</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    current <span class="token operator">:=</span> n</span>
<span class="line">    <span class="token keyword">for</span> current <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Print</span><span class="token punctuation">(</span>current<span class="token punctuation">.</span>Value<span class="token punctuation">,</span> <span class="token string">&quot; -&gt; &quot;</span><span class="token punctuation">)</span></span>
<span class="line">        current <span class="token operator">=</span> current<span class="token punctuation">.</span>Next</span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;nil&quot;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Создаём цепочку</span></span>
<span class="line">    head <span class="token operator">:=</span> <span class="token operator">&amp;</span>Node<span class="token punctuation">{</span>Value<span class="token punctuation">:</span> <span class="token number">1</span><span class="token punctuation">}</span></span>
<span class="line">    head<span class="token punctuation">.</span>Next <span class="token operator">=</span> <span class="token operator">&amp;</span>Node<span class="token punctuation">{</span>Value<span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">}</span></span>
<span class="line">    head<span class="token punctuation">.</span>Next<span class="token punctuation">.</span>Next <span class="token operator">=</span> <span class="token operator">&amp;</span>Node<span class="token punctuation">{</span>Value<span class="token punctuation">:</span> <span class="token number">3</span><span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    head<span class="token punctuation">.</span><span class="token function">PrintChain</span><span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token comment">// 1 -&gt; 2 -&gt; 3 -&gt; nil</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Меняем через указатель</span></span>
<span class="line">    head<span class="token punctuation">.</span>Next<span class="token punctuation">.</span>Value <span class="token operator">=</span> <span class="token number">20</span></span>
<span class="line">    head<span class="token punctuation">.</span><span class="token function">PrintChain</span><span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token comment">// 1 -&gt; 20 -&gt; 3 -&gt; nil</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Разрываем цепочку</span></span>
<span class="line">    head<span class="token punctuation">.</span>Next <span class="token operator">=</span> <span class="token boolean">nil</span></span>
<span class="line">    head<span class="token punctuation">.</span><span class="token function">PrintChain</span><span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token comment">// 1 -&gt; nil</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>Что происходит?</strong> Каждая Node ссылается на следующую через указатель. Метод PrintChain использует pointer receiver для доступа.</li><li><strong>Зачем?</strong> Для динамических структур данных (списки, деревья). Без указателей пришлось бы встраивать (embedded), но это не гибко.</li></ul><h4 id="пример-5-nil-в-полях-указателях-и-проверка" tabindex="-1"><a class="header-anchor" href="#пример-5-nil-в-полях-указателях-и-проверка"><span>Пример 5: Nil в полях-указателях и проверка</span></a></h4><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token string">&quot;fmt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Book <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Title  <span class="token builtin">string</span></span>
<span class="line">    Author <span class="token operator">*</span><span class="token builtin">string</span>  <span class="token comment">// Указатель на string (опциональный автор)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">printBook</span><span class="token punctuation">(</span>b Book<span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Print</span><span class="token punctuation">(</span>b<span class="token punctuation">.</span>Title<span class="token punctuation">)</span></span>
<span class="line">    <span class="token keyword">if</span> b<span class="token punctuation">.</span>Author <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot; (Автор неизвестен)&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot; by&quot;</span><span class="token punctuation">,</span> <span class="token operator">*</span>b<span class="token punctuation">.</span>Author<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    b1 <span class="token operator">:=</span> Book<span class="token punctuation">{</span>Title<span class="token punctuation">:</span> <span class="token string">&quot;Go Programming&quot;</span><span class="token punctuation">}</span></span>
<span class="line">    <span class="token function">printBook</span><span class="token punctuation">(</span>b1<span class="token punctuation">)</span>  <span class="token comment">// Go Programming (Автор неизвестен)</span></span>
<span class="line">    </span>
<span class="line">    author <span class="token operator">:=</span> <span class="token string">&quot;Russ Cox&quot;</span></span>
<span class="line">    b2 <span class="token operator">:=</span> Book<span class="token punctuation">{</span>Title<span class="token punctuation">:</span> <span class="token string">&quot;Effective Go&quot;</span><span class="token punctuation">,</span> Author<span class="token punctuation">:</span> <span class="token operator">&amp;</span>author<span class="token punctuation">}</span></span>
<span class="line">    <span class="token function">printBook</span><span class="token punctuation">(</span>b2<span class="token punctuation">)</span>  <span class="token comment">// Effective Go by Russ Cox</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>Зачем?</strong> Для обработки отсутствующих данных без zero-values (пустая строка — это не то же, что &quot;нет автора&quot;).</li></ul><h4 id="советы-по-использованию" tabindex="-1"><a class="header-anchor" href="#советы-по-использованию"><span>Советы по использованию</span></a></h4><ul><li><strong>Когда использовать указатели в полях</strong>: Для опциональных или больших вложенных типов. Избегай циклических ссылок (A указывает на B, B на A) — может привести к утечкам памяти.</li><li><strong>В методах</strong>: Если метод меняет структуру — используй <code>*Struct</code>. Если только читает — value receiver.</li><li><strong>Ошибки</strong>: Dereferencing nil поля — panic. Всегда проверяй <code>if field != nil</code>.</li><li><strong>JSON и т.д.</strong>: В encoding/json указатели позволяют marshal в null.</li><li><strong>Практика</strong>: Создай структуру Person с *Address (Address — другая struct). Напиши метод для обновления адреса.</li></ul><h3 id="встроенные-структуры-с-указателями-в-go-подробное-объяснение-с-примерами" tabindex="-1"><a class="header-anchor" href="#встроенные-структуры-с-указателями-в-go-подробное-объяснение-с-примерами"><span>Встроенные структуры с указателями в Go: Подробное объяснение с примерами</span></a></h3><p>Продолжаем изучение Go! Встроенные структуры (embedded structs или anonymous fields) — это мощная фича Go, которая позволяет одной структуре &quot;встраивать&quot; другую без указания имени поля. Это даёт <strong>промоушен</strong> (promotion) полей и методов: поля и методы встроенной структуры становятся доступны напрямую в родительской структуре, как будто они её собственные.</p><p>Теперь про <strong>встроенные структуры с указателями</strong> (<code>*Struct</code> как anonymous field). Это комбинация embedding и указателей. Вместо встраивания value-структуры, мы встраиваем указатель на структуру. Это добавляет гибкость:</p><ul><li><strong>Nil-возможность</strong>: Встроенная часть может быть nil (отсутствовать), что полезно для опциональных компонентов.</li><li><strong>Изменяемость</strong>: Легко менять встроенную часть динамически.</li><li><strong>Экономия памяти</strong>: Указатель занимает мало места, и можно делить данные между структурами.</li><li><strong>Промоушен с оговорками</strong>: Поля и методы доступны, но нужно учитывать nil (иначе panic).</li></ul><p><strong>Зачем это использовать?</strong></p><ul><li>Для композиции (composition) вместо наследования: Например, базовая структура &quot;Person&quot; встраивается в &quot;Employee&quot; как указатель, чтобы Employee мог иметь или не иметь Person-данных.</li><li>Опциональные части: Встроенная структура может быть инициализирована позже или оставлена nil.</li><li>Динамика: Легко заменять встроенную часть на другую.</li><li>Но: Это реже используется, чем простое embedding, потому что добавляет проверки на nil. Если не нужна nil-возможность, лучше встраивать value.</li></ul><p><strong>Важно</strong>: При доступе к промотированным полям через указатель Go упрощает синтаксис (не нужно <code>*</code>), но всегда проверяй на nil. Если встроенный указатель nil, доступ к его полям — panic.</p><p>Давай разберём на примерах. Код можно скопировать и запустить.</p><h4 id="пример-1-базовое-встраивание-с-указателем-promotion-полеи" tabindex="-1"><a class="header-anchor" href="#пример-1-базовое-встраивание-с-указателем-promotion-полеи"><span>Пример 1: Базовое встраивание с указателем (promotion полей)</span></a></h4><p>Сначала напомню простое embedding без указателя:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token string">&quot;fmt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Address <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    City <span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Person <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Name <span class="token builtin">string</span></span>
<span class="line">    Address  <span class="token comment">// Встроенная (value)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    p <span class="token operator">:=</span> Person<span class="token punctuation">{</span>Name<span class="token punctuation">:</span> <span class="token string">&quot;Alice&quot;</span><span class="token punctuation">,</span> Address<span class="token punctuation">:</span> Address<span class="token punctuation">{</span>City<span class="token punctuation">:</span> <span class="token string">&quot;New York&quot;</span><span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>p<span class="token punctuation">.</span>City<span class="token punctuation">)</span>  <span class="token comment">// Promotion: доступ напрямую (New York)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Теперь с указателем:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token string">&quot;fmt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Address <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    City <span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Person <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Name <span class="token builtin">string</span></span>
<span class="line">    <span class="token operator">*</span>Address  <span class="token comment">// Встроенная как указатель (anonymous)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Без адреса (nil)</span></span>
<span class="line">    p1 <span class="token operator">:=</span> Person<span class="token punctuation">{</span>Name<span class="token punctuation">:</span> <span class="token string">&quot;Alice&quot;</span><span class="token punctuation">}</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;p1.City:&quot;</span><span class="token punctuation">,</span> p1<span class="token punctuation">.</span>City<span class="token punctuation">)</span>  <span class="token comment">// Panic! Если раскомментировать: nil dereference</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// С адресом</span></span>
<span class="line">    addr <span class="token operator">:=</span> Address<span class="token punctuation">{</span>City<span class="token punctuation">:</span> <span class="token string">&quot;New York&quot;</span><span class="token punctuation">}</span></span>
<span class="line">    p2 <span class="token operator">:=</span> Person<span class="token punctuation">{</span>Name<span class="token punctuation">:</span> <span class="token string">&quot;Bob&quot;</span><span class="token punctuation">,</span> Address<span class="token punctuation">:</span> <span class="token operator">&amp;</span>addr<span class="token punctuation">}</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;p2.City:&quot;</span><span class="token punctuation">,</span> p2<span class="token punctuation">.</span>City<span class="token punctuation">)</span>  <span class="token comment">// New York (promotion работает)</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Меняем через promotion</span></span>
<span class="line">    p2<span class="token punctuation">.</span>City <span class="token operator">=</span> <span class="token string">&quot;London&quot;</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Новый город:&quot;</span><span class="token punctuation">,</span> addr<span class="token punctuation">.</span>City<span class="token punctuation">)</span>  <span class="token comment">// London (изменился оригинал)</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Проверяем на nil</span></span>
<span class="line">    <span class="token keyword">if</span> p2<span class="token punctuation">.</span>Address <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Адрес есть:&quot;</span><span class="token punctuation">,</span> p2<span class="token punctuation">.</span>City<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Делаем nil</span></span>
<span class="line">    p2<span class="token punctuation">.</span>Address <span class="token operator">=</span> <span class="token boolean">nil</span></span>
<span class="line">    <span class="token keyword">if</span> p2<span class="token punctuation">.</span>Address <span class="token operator">==</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Адрес удалён&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>Что происходит?</strong> <code>*Address</code> встроен анонимно, так что <code>p.City</code> — это shortcut для <code>p.Address.City</code> (Go автоматически dereference). Но если Address nil, доступ к City — ошибка.</li><li><strong>Зачем?</strong> Для опциональных вложенных данных (например, Person может иметь или не иметь Address).</li></ul><h4 id="пример-2-promotion-методов-с-указателем" tabindex="-1"><a class="header-anchor" href="#пример-2-promotion-методов-с-указателем"><span>Пример 2: Promotion методов с указателем</span></a></h4><p>Методы встроенной структуры тоже промотируются. С указателем метод вызывается на *Address (pointer receiver работает).</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token string">&quot;fmt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Address <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    City <span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Метод на pointer receiver</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>a <span class="token operator">*</span>Address<span class="token punctuation">)</span> <span class="token function">ChangeCity</span><span class="token punctuation">(</span>newCity <span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    a<span class="token punctuation">.</span>City <span class="token operator">=</span> newCity</span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token comment">// Метод на value receiver</span></span>
<span class="line"><span class="token keyword">func</span> <span class="token punctuation">(</span>a Address<span class="token punctuation">)</span> <span class="token function">Print</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Город:&quot;</span><span class="token punctuation">,</span> a<span class="token punctuation">.</span>City<span class="token punctuation">)</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Person <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Name <span class="token builtin">string</span></span>
<span class="line">    <span class="token operator">*</span>Address  <span class="token comment">// Встроенная с указателем</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    addr <span class="token operator">:=</span> Address<span class="token punctuation">{</span>City<span class="token punctuation">:</span> <span class="token string">&quot;Paris&quot;</span><span class="token punctuation">}</span></span>
<span class="line">    p <span class="token operator">:=</span> Person<span class="token punctuation">{</span>Name<span class="token punctuation">:</span> <span class="token string">&quot;Charlie&quot;</span><span class="token punctuation">,</span> Address<span class="token punctuation">:</span> <span class="token operator">&amp;</span>addr<span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Promotion метода: вызываем напрямую</span></span>
<span class="line">    p<span class="token punctuation">.</span><span class="token function">ChangeCity</span><span class="token punctuation">(</span><span class="token string">&quot;Berlin&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Новый город:&quot;</span><span class="token punctuation">,</span> p<span class="token punctuation">.</span>City<span class="token punctuation">)</span>  <span class="token comment">// Berlin</span></span>
<span class="line">    </span>
<span class="line">    p<span class="token punctuation">.</span><span class="token function">Print</span><span class="token punctuation">(</span><span class="token punctuation">)</span>  <span class="token comment">// Город: Berlin (value-метод тоже работает)</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Если nil</span></span>
<span class="line">    p<span class="token punctuation">.</span>Address <span class="token operator">=</span> <span class="token boolean">nil</span></span>
<span class="line">    <span class="token comment">// p.Print()  // Panic! nil dereference</span></span>
<span class="line">    <span class="token keyword">if</span> p<span class="token punctuation">.</span>Address <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        p<span class="token punctuation">.</span><span class="token function">Print</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Нет адреса&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>Что происходит?</strong> Методы промотируются, но если указатель nil, вызов — panic. Pointer receivers идеальны для изменений.</li><li><strong>Зачем?</strong> Для расширения поведения: Person &quot;наследует&quot; методы Address, но с опцией nil.</li></ul><h4 id="пример-3-встраивание-нескольких-с-указателями-множественное-наследование" tabindex="-1"><a class="header-anchor" href="#пример-3-встраивание-нескольких-с-указателями-множественное-наследование"><span>Пример 3: Встраивание нескольких с указателями (множественное &quot;наследование&quot;)</span></a></h4><p>Go позволяет встраивать несколько, но если поля/методы конфликтуют — нужно уточнять.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token string">&quot;fmt&quot;</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Contact <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Email <span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Location <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    City <span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> User <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Name <span class="token builtin">string</span></span>
<span class="line">    <span class="token operator">*</span>Contact   <span class="token comment">// Встроенная</span></span>
<span class="line">    <span class="token operator">*</span>Location  <span class="token comment">// Встроенная</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    contact <span class="token operator">:=</span> Contact<span class="token punctuation">{</span>Email<span class="token punctuation">:</span> <span class="token string">&quot;user@example.com&quot;</span><span class="token punctuation">}</span></span>
<span class="line">    location <span class="token operator">:=</span> Location<span class="token punctuation">{</span>City<span class="token punctuation">:</span> <span class="token string">&quot;Tokyo&quot;</span><span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    u <span class="token operator">:=</span> User<span class="token punctuation">{</span>Name<span class="token punctuation">:</span> <span class="token string">&quot;David&quot;</span><span class="token punctuation">,</span> Contact<span class="token punctuation">:</span> <span class="token operator">&amp;</span>contact<span class="token punctuation">,</span> Location<span class="token punctuation">:</span> <span class="token operator">&amp;</span>location<span class="token punctuation">}</span></span>
<span class="line">    </span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>u<span class="token punctuation">.</span>Email<span class="token punctuation">)</span>  <span class="token comment">// Promotion от Contact</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>u<span class="token punctuation">.</span>City<span class="token punctuation">)</span>   <span class="token comment">// Promotion от Location</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Меняем</span></span>
<span class="line">    u<span class="token punctuation">.</span>Email <span class="token operator">=</span> <span class="token string">&quot;new@example.com&quot;</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>contact<span class="token punctuation">.</span>Email<span class="token punctuation">)</span>  <span class="token comment">// new@example.com</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// Nil одна часть</span></span>
<span class="line">    u<span class="token punctuation">.</span>Location <span class="token operator">=</span> <span class="token boolean">nil</span></span>
<span class="line">    <span class="token keyword">if</span> u<span class="token punctuation">.</span>Location <span class="token operator">!=</span> <span class="token boolean">nil</span> <span class="token punctuation">{</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span>u<span class="token punctuation">.</span>City<span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span> <span class="token keyword">else</span> <span class="token punctuation">{</span></span>
<span class="line">        fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token string">&quot;Нет локации&quot;</span><span class="token punctuation">)</span></span>
<span class="line">    <span class="token punctuation">}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>Зачем?</strong> Для композиции из нескольких частей, каждая из которых опциональна (например, User может иметь Contact, но не Location).</li></ul><h4 id="пример-4-инициализация-и-json-практическии-случаи" tabindex="-1"><a class="header-anchor" href="#пример-4-инициализация-и-json-практическии-случаи"><span>Пример 4: Инициализация и JSON (практический случай)</span></a></h4><p>Встраивание с указателями полезно в JSON: nil — null в выводе.</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">package</span> main</span>
<span class="line"></span>
<span class="line"><span class="token keyword">import</span> <span class="token punctuation">(</span></span>
<span class="line">    <span class="token string">&quot;encoding/json&quot;</span></span>
<span class="line">    <span class="token string">&quot;fmt&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Details <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    Notes <span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> Item <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">    ID <span class="token builtin">string</span></span>
<span class="line">    <span class="token operator">*</span>Details  <span class="token comment">// Опциональные детали</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">func</span> <span class="token function">main</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span></span>
<span class="line">    <span class="token comment">// Без деталей</span></span>
<span class="line">    i1 <span class="token operator">:=</span> Item<span class="token punctuation">{</span>ID<span class="token punctuation">:</span> <span class="token string">&quot;001&quot;</span><span class="token punctuation">}</span></span>
<span class="line">    data1<span class="token punctuation">,</span> <span class="token boolean">_</span> <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Marshal</span><span class="token punctuation">(</span>i1<span class="token punctuation">)</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token function">string</span><span class="token punctuation">(</span>data1<span class="token punctuation">)</span><span class="token punctuation">)</span>  <span class="token comment">// {&quot;ID&quot;:&quot;001&quot;,&quot;Details&quot;:null}</span></span>
<span class="line">    </span>
<span class="line">    <span class="token comment">// С деталями</span></span>
<span class="line">    details <span class="token operator">:=</span> Details<span class="token punctuation">{</span>Notes<span class="token punctuation">:</span> <span class="token string">&quot;Important&quot;</span><span class="token punctuation">}</span></span>
<span class="line">    i2 <span class="token operator">:=</span> Item<span class="token punctuation">{</span>ID<span class="token punctuation">:</span> <span class="token string">&quot;002&quot;</span><span class="token punctuation">,</span> Details<span class="token punctuation">:</span> <span class="token operator">&amp;</span>details<span class="token punctuation">}</span></span>
<span class="line">    data2<span class="token punctuation">,</span> <span class="token boolean">_</span> <span class="token operator">:=</span> json<span class="token punctuation">.</span><span class="token function">Marshal</span><span class="token punctuation">(</span>i2<span class="token punctuation">)</span></span>
<span class="line">    fmt<span class="token punctuation">.</span><span class="token function">Println</span><span class="token punctuation">(</span><span class="token function">string</span><span class="token punctuation">(</span>data2<span class="token punctuation">)</span><span class="token punctuation">)</span>  <span class="token comment">// {&quot;ID&quot;:&quot;002&quot;,&quot;Details&quot;:{&quot;Notes&quot;:&quot;Important&quot;}}</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li><strong>Зачем?</strong> В API или сериализации: Опциональные вложенные объекты как null, а не пустые {}.</li></ul><h4 id="советы-по-использованию-1" tabindex="-1"><a class="header-anchor" href="#советы-по-использованию-1"><span>Советы по использованию</span></a></h4><ul><li><strong>Проверки</strong>: Всегда <code>if embedded != nil</code> перед доступом к промотированным полям/методам.</li><li><strong>Конфликты</strong>: Если два embedded имеют одинаковые поля, уточняй: <code>p.Address.City</code> вместо <code>p.City</code>.</li><li><strong>Когда избегать</strong>: Если не нужна nil-возможность, встраивай value — проще и без panic-рисков.</li><li><strong>Производительность</strong>: Embedding бесплатно (нет overhead), указатель добавляет indiirection, но незначительно.</li><li><strong>Практика</strong>: Создай структуру Car с встроенным *Engine. Напиши метод Start(), который проверяет nil.</li></ul><p>Читать дальше - [[05 - Другие виды указателей]]</p>`,60)])])}const o=s(t,[["render",l]]),u=JSON.parse('{"path":"/guide/pointers/structure-pointers.html","title":"Указатели в структурах","lang":"ru-RU","frontmatter":{},"headers":[{"level":3,"title":"Встроенные структуры с указателями в Go: Подробное объяснение с примерами","slug":"встроенные-структуры-с-указателями-в-go-подробное-объяснение-с-примерами","link":"#встроенные-структуры-с-указателями-в-go-подробное-объяснение-с-примерами","children":[]}],"git":{"updatedTime":1762634020000,"contributors":[{"name":"Danil Chugaev","username":"","email":"dmchugaev@gmail.com","commits":1}],"changelog":[{"hash":"7d28f9cefa2cdea75dd65ef50a0d72ce2e0ad1b6","time":1762634020000,"email":"dmchugaev@gmail.com","author":"Danil Chugaev","message":"upd"}]},"filePathRelative":"guide/pointers/structure-pointers.md"}');export{o as comp,u as data};
